{
  "$schema": "https://open-design.ai/schemas/plugin.v1.json",
  "specVersion": "1.0.0",
  "name": "example-pricing-page",
  "title": "Pricing Page",
  "title_i18n": {
    "zh-CN": "价格页面",
    "zh-TW": "價格頁面",
    "ja": "料金ページ",
    "ko": "가격 페이지",
    "de": "Preisseite",
    "fr": "Page de tarification",
    "ru": "Страница с ценами",
    "es": "Página de precios",
    "pt-BR": "Página de preços",
    "it": "Pagina dei prezzi",
    "vi": "Trang giá",
    "pl": "Strona cennikowa",
    "id": "Halaman harga",
    "nl": "Prijzenpagina",
    "ar": "صفحة التسعير",
    "tr": "Fiyatlandırma sayfası",
    "uk": "Сторінка з цінами",
    "en": "Pricing Page"
  },
  "version": "0.1.0",
  "description": "A standalone pricing page — header, plan tiers, feature comparison table, and an FAQ. Use when the brief asks for \"pricing\", \"plans\", \"subscription tiers\", or a \"compare plans\" page.",
  "description_i18n": {
    "zh-CN": "独立的价格页面 — 包含页眉、套餐层级、功能对比表和常见问题。适用于需要'价格'、'套餐'、'订阅层级'或'对比套餐'页面的需求。",
    "zh-TW": "獨立的價格頁面 — 包含頁首、方案層級、功能對比表和常見問題。適用於需要「價格」、「方案」、「訂閱層級」或「對比方案」頁面的需求。",
    "ja": "独立した料金ページ — ヘッダー、プラン階層、機能比較表、FAQを含みます。「料金」「プラン」「サブスクリプション階層」または「プラン比較」ページが必要な場合に使用します。",
    "ko": "독립형 가격 페이지 — 헤더, 플랜 등급, 기능 비교표 및 FAQ 포함. '가격', '플랜', '구독 등급' 또는 '플랜 비교' 페이지가 필要할 때 사용하세요.",
    "de": "Eine eigenständige Preisseite – Header, Tarif-Stufen, Feature-Vergleichstabelle und FAQ. Verwenden Sie diese, wenn das Briefing nach 'Preisen', 'Plänen', 'Abo-Stufen' oder einer 'Tarife vergleichen'-Seite verlangt.",
    "fr": "Une page de tarification autonome — en-tête, niveaux de forfaits, tableau comparatif des fonctionnalités et FAQ. À utiliser lorsque le brief demande une page 'tarifs', 'forfaits', 'niveaux d'abonnement' ou 'comparer les forfaits'.",
    "ru": "Отдельная страница с ценами — заголовок, уровни тарифов, таблица сравнения функций и FAQ. Используйте, когда в брифе требуется страница с 'ценами', 'тарифами', 'уровнями подписки' или 'сравнением тарифов'.",
    "es": "Una página de precios independiente — encabezado, niveles de planes, tabla comparativa de características y preguntas frecuentes. Úsala cuando el brief solicite 'precios', 'planes', 'niveles de suscripción' o una página de 'comparar planes'.",
    "pt-BR": "Uma página de preços autônoma — cabeçalho, níveis de planos, tabela de comparação de recursos e perguntas frequentes. Use quando o briefing solicitar 'preços', 'planos', 'níveis de assinatura' ou uma página de 'comparar planos'.",
    "it": "Una pagina dei prezzi autonoma — intestazione, livelli di piani, tabella di confronto delle funzionalità e FAQ. Da usare quando il brief richiede una pagina per 'prezzi', 'piani', 'livelli di abbonamento' o 'confronta piani'.",
    "vi": "Trang giá độc lập — tiêu đề, các cấp gói dịch vụ, bảng so sánh tính năng và câu hỏi thường gặp. Sử dụng khi yêu cầu có trang 'giá', 'gói dịch vụ', 'cấp đăng ký' hoặc 'so sánh gói'.",
    "pl": "Samodzielna strona cennikowa — nagłówek, poziomy planów, tabela porównania funkcji i FAQ. Używaj, gdy brief wymaga strony z 'cennikiem', 'planami', 'poziomami subskrypcji' lub 'porównaniem planów'.",
    "id": "Halaman harga mandiri — header, tingkat paket, tabel perbandingan fitur, dan FAQ. Gunakan saat brief meminta halaman 'harga', 'paket', 'tingkat langganan', atau 'bandingkan paket'.",
    "nl": "Een standalone prijzenpagina — header, abonnementsniveaus, functievergelijkingstabel en FAQ. Gebruik wanneer de briefing vraagt om 'prijzen', 'abonnementen', 'abonnementsniveaus' of een 'vergelijk abonnementen'-pagina.",
    "ar": "صفحة تسعير مستقلة — رأس الصفحة، مستويات الخطط، جدول مقارنة الميزات، والأسئلة الشائعة. استخدمها عندما يطلب الموجز صفحة 'تسعير' أو 'خطط' أو 'مستويات الاشتراك' أو 'مقارنة الخطط'.",
    "tr": "Bağımsız bir fiyatlandırma sayfası — başlık, plan seviyeleri, özellik karşılaştırma tablosu ve SSS. Brief 'fiyatlandırma', 'planlar', 'abonelik seviyeleri' veya 'planları karşılaştır' sayfası istediğinde kullanın.",
    "uk": "Окрема сторінка з цінами — заголовок, рівні тарифів, таблиця порівняння функцій та FAQ. Використовуйте, коли бриф вимагає сторінку з 'цінами', 'тарифами', 'рівнями підписки' або 'порівнянням тарифів'.",
    "en": "A standalone pricing page — header, plan tiers, feature comparison table, and an FAQ. Use when the brief asks for \"pricing\", \"plans\", \"subscription tiers\", or a \"compare plans\" page."
  },
  "license": "MIT",
  "author": {
    "name": "Open Design",
    "url": "https://github.com/nexu-io"
  },
  "homepage": "https://github.com/nexu-io/open-design/tree/main/plugins/_official/examples/pricing-page",
  "tags": [
    "example",
    "first-party",
    "prototype",
    "sales",
    "web",
    "desktop",
    "pricing",
    "pricing-page",
    "plans",
    "subscription",
    "compare-plans",
    "untitled"
  ],
  "compat": {
    "agentSkills": [
      {
        "path": "./SKILL.md"
      }
    ]
  },
  "od": {
    "kind": "scenario",
    "taskKind": "new-generation",
    "mode": "prototype",
    "platform": "desktop",
    "scenario": "sales",
    "surface": "web",
    "preview": {
      "type": "html",
      "entry": "./example.html"
    },
    "useCase": {
      "query": {
        "en": "A standalone pricing page — header, plan tiers, feature comparison table, and an FAQ. Use when the brief asks for \"pricing\", \"plans\", \"subscription tiers\", or a \"compare plans\" page.",
        "zh-CN": "使用这个插件完成以下任务：A standalone pricing page — header, plan tiers, feature comparison table, and an FAQ. Use when the brief asks for \"pricing\", \"plans\", \"subscription tiers\", or a \"compare plans\" page."
      },
      "exampleOutputs": [
        {
          "path": "./example.html",
          "title": "Pricing Page"
        }
      ]
    },
    "context": {
      "skills": [
        {
          "path": "./SKILL.md"
        }
      ],
      "designSystem": {
        "primary": true
      },
      "craft": [
        "laws-of-ux"
      ],
      "assets": [
        "./example.html"
      ]
    },
    "pipeline": {
      "stages": [
        {
          "id": "generate",
          "atoms": [
            "file-write",
            "live-artifact"
          ]
        }
      ]
    },
    "capabilities": [
      "prompt:inject",
      "fs:write"
    ]
  }
}
